import java.util.*;
import org.json.*;

public class TestLifecycle {
    static int staticCounter = 0;
    static HashMap<String, Object> globalMap = new HashMap<>();

    public static void main(String[] args) throws Exception {
        System.out.println("=== Test Lifecycle ===");

        // Test static counter persistence
        staticCounter++;
        System.out.println("Static counter: " + staticCounter);

        // Test global map persistence
        globalMap.put("iteration", staticCounter);
        System.out.println("Global map: " + globalMap);

        // Test variable scope
        int localVar = 42;
        System.out.println("Local variable: " + localVar);

        // Test class definition
        class InnerClass {
            String name;
            InnerClass(String name) { this.name = name; }
            String getName() { return name; }
        }
        InnerClass inner = new InnerClass("test");
        System.out.println("Inner class: " + inner.getName());

        System.out.println("=== Lifecycle Test Complete ===");
    }
}

