import java.lang.reflect.*;

public class TestReflection {
    public static void main(String[] args) throws Exception {
        System.out.println("=== Reflection Test ===");

        // Test basic reflection
        Class<?> clazz = Class.forName("android.os.Build");
        System.out.println("Class: " + clazz.getName());

        // Test accessing fields
        Field[] fields = clazz.getDeclaredFields();
        System.out.println("Fields count: " + fields.length);

        // Test accessing methods
        Method[] methods = clazz.getDeclaredMethods();
        System.out.println("Methods count: " + methods.length);

        // Test creating instance
        try {
            Object instance = clazz.newInstance();
            System.out.println("Instance created: " + instance.getClass().getName());
        } catch (Exception e) {
            System.out.println("Instance creation failed: " + e.getMessage());
        }

        System.out.println("=== Reflection Test Complete ===");
    }
}

public class TestThread {
    public static void main(String[] args) throws Exception {
        System.out.println("=== Thread Test ===");

        // Test basic thread
        Thread t = new Thread(() -> {
            System.out.println("Thread running: " + Thread.currentThread().getName());
        });
        t.start();
        t.join(1000);

        System.out.println("Thread completed");

        // Test multiple threads
        for (int i = 0; i < 3; i++) {
            final int id = i;
            new Thread(() -> {
                System.out.println("Thread " + id + " running");
            }).start();
        }

        Thread.sleep(500);
        System.out.println("All threads started");

        System.out.println("=== Thread Test Complete ===");
    }
}

import java.util.concurrent.*;

public class TestExecutor {
    public static void main(String[] args) throws Exception {
        System.out.println("=== ExecutorService Test ===");

        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 5; i++) {
            final int id = i;
            executor.submit(() -> {
                System.out.println("Task " + id + " executed by " + 
                    Thread.currentThread().getName());
            });
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("All tasks completed");

        System.out.println("=== ExecutorService Test Complete ===");
    }
}

import java.io.*;
