public class TestSharedState {
    private static final String STATE_FILE = "/data/local/tmp/state.txt";

    public static void main(String[] args) throws Exception {
        System.out.println("=== Shared State Test ===");

        // Try to read existing state
        int counter = 0;
        try {
            String content = new String(Files.readAllBytes(Paths.get(STATE_FILE)));
            counter = Integer.parseInt(content.trim());
            System.out.println("Read counter: " + counter);
        } catch (Exception e) {
            System.out.println("No existing state: " + e.getMessage());
        }

        // Increment counter
        counter++;
        System.out.println("New counter: " + counter);

        // Write state
        Files.write(Paths.get(STATE_FILE), Integer.toString(counter).getBytes());
        System.out.println("State saved");

        System.out.println("=== Shared State Test Complete ===");
    }
}

import java.util.*;

public class TestHashMapPerf {
    public static void main(String[] args) throws Exception {
        System.out.println("=== HashMap Performance Test ===");

        HashMap<String, Integer> map = new HashMap<>();
        int count = 10000;

        // Insert performance
        long start = System.currentTimeMillis();
        for (int i = 0; i < count; i++) {
            map.put("key" + i, i);
        }
        long insertTime = System.currentTimeMillis() - start;
        System.out.println("Insert " + count + " items: " + insertTime + "ms");

        // Lookup performance
        start = System.currentTimeMillis();
        for (int i = 0; i < count; i++) {
            map.get("key" + i);
        }
        long lookupTime = System.currentTimeMillis() - start;
        System.out.println("Lookup " + count + " items: " + lookupTime + "ms");

        System.out.println("=== HashMap Performance Test Complete ===");
    }
}

