import java.net.*;
import java.io.*;

public class TestSocket {
    public static void main(String[] args) throws Exception {
        System.out.println("=== Socket Test ===");

        try {
            // Try to create a socket
            Socket socket = new Socket();
            System.out.println("Socket created");

            // Try to connect to a test server
            socket.connect(new InetSocketAddress("example.com", 80), 5000);
            System.out.println("Connected to example.com:80");

            // Send HTTP request
            OutputStream out = socket.getOutputStream();
            out.write("GET / HTTP/1.1
Host: example.com

".getBytes());
            out.flush();

            // Read response
            InputStream in = socket.getInputStream();
            byte[] buffer = new byte[1024];
            int bytesRead = in.read(buffer);
            String response = new String(buffer, 0, bytesRead);
            System.out.println("Response length: " + response.length());

            socket.close();
            System.out.println("Socket closed");
        } catch (Exception e) {
            System.out.println("Socket error: " + e.getClass().getName() + ": " + e.getMessage());
        }

        System.out.println("=== Socket Test Complete ===");
    }
}

